-- Migración 0028. DISPOSITIVOS_TIPOS clasifica equipos por marca y modelo.
-- DISPOSITIVOS pasa a exigir ID_TIPO. No editar este archivo.
-- El siguiente cambio va en una migración nueva y debe reflejarse en db/init.sql.

BEGIN;

CREATE TABLE "DISPOSITIVOS_TIPOS" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CODIGO" text NOT NULL UNIQUE,
  "NOMBRE" text NOT NULL,
  "MARCA" text NOT NULL,
  "MODELO" text NOT NULL,
  "SISTEMA_OPERATIVO" text NOT NULL,
  "VERSION_SO_MINIMA" text,
  "NUMERO_PARTE" text,
  "TIENE_ESCANER" boolean NOT NULL DEFAULT true,
  "DESCRIPCION" text,
  "ACTIVO" boolean NOT NULL DEFAULT true,
  "ES_SEMILLA" boolean NOT NULL DEFAULT false,
  "CREADO_EN" timestamptz NOT NULL DEFAULT now(),
  "ACTUALIZADO_EN" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "DISPOSITIVOS_TIPOS_CODIGO_CHK" CHECK (
    length(btrim("CODIGO")) > 0
  ),
  CONSTRAINT "DISPOSITIVOS_TIPOS_NOMBRE_CHK" CHECK (
    length(btrim("NOMBRE")) > 0
  ),
  CONSTRAINT "DISPOSITIVOS_TIPOS_MARCA_CHK" CHECK (
    length(btrim("MARCA")) > 0
  ),
  CONSTRAINT "DISPOSITIVOS_TIPOS_MODELO_CHK" CHECK (
    length(btrim("MODELO")) > 0
  ),
  CONSTRAINT "DISPOSITIVOS_TIPOS_SISTEMA_OPERATIVO_CHK" CHECK (
    length(btrim("SISTEMA_OPERATIVO")) > 0
  ),
  CONSTRAINT "DISPOSITIVOS_TIPOS_VERSION_SO_MINIMA_CHK" CHECK (
    "VERSION_SO_MINIMA" IS NULL OR length(btrim("VERSION_SO_MINIMA")) > 0
  ),
  CONSTRAINT "DISPOSITIVOS_TIPOS_NUMERO_PARTE_CHK" CHECK (
    "NUMERO_PARTE" IS NULL OR length(btrim("NUMERO_PARTE")) > 0
  ),
  CONSTRAINT "DISPOSITIVOS_TIPOS_DESCRIPCION_CHK" CHECK (
    "DESCRIPCION" IS NULL OR length(btrim("DESCRIPCION")) > 0
  )
);

CREATE INDEX "DISPOSITIVOS_TIPOS_MARCA_MODELO_IDX"
  ON "DISPOSITIVOS_TIPOS" ("MARCA", "MODELO");

-- Requiere DISPOSITIVOS vacía (o sin filas sin tipo). Si ya hay equipos,
-- créales un tipo y asígnalo antes de exigir NOT NULL.
ALTER TABLE "DISPOSITIVOS"
  ADD COLUMN "ID_TIPO" integer NOT NULL,
  ADD CONSTRAINT "DISPOSITIVOS_ID_TIPO_FK"
    FOREIGN KEY ("ID_TIPO") REFERENCES "DISPOSITIVOS_TIPOS" ("ID");

CREATE INDEX "DISPOSITIVOS_ID_TIPO_IDX" ON "DISPOSITIVOS" ("ID_TIPO");

CREATE TRIGGER "DISPOSITIVOS_TIPOS_ACTUALIZADO_TRG"
  BEFORE UPDATE ON "DISPOSITIVOS_TIPOS"
  FOR EACH ROW
  EXECUTE FUNCTION marcar_actualizado_en();

ALTER TABLE "DISPOSITIVOS_TIPOS" OWNER TO packing;

COMMIT;
